def test_readme_example():
    """Test the exact sequence from README"""
    print("Testing README example...")

    try:
        import pam
        p = pam.authenticate()
        print(f"✅ Line 27: p = pam.authenticate() -> {type(p)}")

        # Test first authenticate call
        try:
            result1 = p.authenticate('david', 'correctpassword')
            print(f"✅ Line 28: p.authenticate('david', 'correctpassword') -> {result1} ({type(result1)})")
        except Exception as e:
            print(f"❌ Line 28 failed: {e}")

        # Test second authenticate call  
        try:
            result2 = p.authenticate('david', 'badpassword')
            print(f"✅ Line 30: p.authenticate('david', 'badpassword') -> {result2} ({type(result2)})")
        except Exception as e:
            print(f"❌ Line 30 failed: {e}")

        # Test with service parameter
        try:
            result3 = p.authenticate('david', 'correctpassword', service='login')
            print(f"✅ Line 32: p.authenticate('david', 'correctpassword', service='login') -> {result3} ({type(result3)})")
        except Exception as e:
            print(f"❌ Line 32 failed: {e}")

        # Test attributes
        try:
            code_reason = '{} {}'.format(p.code, p.reason)
            print(f"✅ Line 40: print('{{}}{{}}'.format(p.code, p.reason)) -> '{code_reason}'")
        except Exception as e:
            print(f"❌ Line 40 failed: {e}")

    except Exception as e:
        print(f"❌ README example failed: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    test_readme_example()

